// Combining marks (U+0300-U+036F) that follow a Latin-script base letter.
// Anchoring on Latin keeps Cyrillic (e.g. й), Greek, Hangul, etc. untouched.
const LATIN_MARKS = /(\p{Script=Latin})[̀-ͯ]+/gu;

function foldDiacritics(s) {
  return s.normalize('NFD').replace(LATIN_MARKS, '$1').normalize('NFC');
}

/**
 * Convert a string into a lowercase, dash-separated URL slug.
 * Latin diacritics are folded to their base letters (Crème -> creme).
 * Non-decomposable letters (ß, ø, æ, ł) and non-Latin scripts are kept as-is.
 * @param {string} str
 * @returns {string}
 */
export function slugify(str) {
  return foldDiacritics(String(str).toLowerCase().trim())
    .replace(/[^\p{L}\p{N}]+/gu, '-')
    .replace(/^-+|-+$/g, '');
}

