add = r"""
  it('returns empty string for empty input', () => {
    expect(slugify('')).toBe('');
  });

  it('folds multiple marks', () => {
    expect(slugify('Åñö')).toBe('ano');
  });

  it('folds uppercase accented letters', () => {
    expect(slugify('ÉCOLE Élémentaire')).toBe('ecole-elementaire');
  });

  it('folds accents amid punctuation', () => {
    expect(slugify('  Café, Crème & Thé!  ')).toBe('cafe-creme-the');
  });

  it('treats NFD and NFC input identically', () => {
    const nfd = 'Crème Brûlée';
    expect(slugify(nfd)).toBe('creme-brulee');
    expect(slugify(nfd)).toBe(slugify('Crème Brûlée'));
    expect(slugify('Åñö')).toBe('ano');
    expect(slugify('́')).toBe('');
  });

  it('folds before dash collapsing and keeps coercion', () => {
    expect(slugify('Crème   Brûlée')).toBe('creme-brulee');
    expect(slugify('--Été--')).toBe('ete');
    expect(slugify(42)).toBe('42');
  });

  it('keeps Cyrillic including marked letters (y-breve, yo)', () => {
    expect(slugify('Привет мир')).toBe('привет-мир');
    expect(slugify('Майкл')).toBe('майкл');
    expect(slugify('Ёж')).toBe('ёж');
  });

  it('recomposes Hangul', () => {
    expect(slugify('안녕 세계')).toBe('안녕-세계');
    expect(slugify('안녕 하세요')).toBe('안녕-하세요');
  });

  it('leaves non-Latin marks unchanged', () => {
    const before = (s) =>
      s.toLowerCase().trim().replace(/[^\p{L}\p{N}]+/gu, '-').replace(/^-+|-+$/g, '');
    for (const s of ['हिन्दी', 'Καλημέρα']) {
      expect(slugify(s)).toBe(before(s));
    }
  });

  it('keeps non-decomposable letters', () => {
    expect(slugify('Straße')).toBe('straße');
    expect(slugify('Øresund Łódź')).toBe('øresund-łodz');
  });

  it('keeps arity 1 and exports a function', () => {
    expect(typeof slugify).toBe('function');
    expect(slugify.length).toBe(1);
  });
});
"""
